function validateSmokeOnlyInventory(rows, sourceHash) {
  if (rows.length !== 2 || new Set(rows.map(row => row.name)).size !== 2)
    throw new Error('052 BOTH smoke-only inventory must contain exactly two attempts');
  for (const row of rows) {
    if (!/^(WEBGPU|WEBGL2)-smoke$/.test(row.name) || row.start.full !== false ||
        row.name !== row.start.backend + '-smoke' || row.start.sourceHash !== sourceHash ||
        row.files.some(file => /failure|rejected|incomplete/i.test(file)) ||
        !row.terminal || row.terminal.captureId !== row.start.captureId ||
        row.terminal.status !== 'SAVED_PENDING_VERIFICATION' || row.terminal.arms !== 14 ||
        !row.files.includes('report.json'))
      throw new Error('052 unresolved/failed smoke capture inventory');
  }
  for (const backend of ['WEBGPU', 'WEBGL2'])
    if (!rows.some(row => row.name === backend + '-smoke')) throw new Error('052 smoke backend absent');
}
validateSmokeOnlyInventory(inventory, build.sourceHash);
